mapper.update:
update one_line_strategy_ai_daily_run
set last_status = 'SUCCESS',
    completed_at = now(),
    last_error = null,
    input_tokens = input_tokens + #{inputTokens},
    output_tokens = output_tokens + #{outputTokens},
    search_query_count = search_query_count + #{searchQueryCount}
where generation_date = #{generationDate}
  and last_status = 'RUNNING'
  and api_call_count = #{attemptNo}

update one_line_strategy_ai_daily_run
set last_status = 'FAILED',
    completed_at = now(),
    last_error = #{lastError},
    input_tokens = input_tokens + #{inputTokens},
    output_tokens = output_tokens + #{outputTokens},
    search_query_count = search_query_count + #{searchQueryCount}
where generation_date = #{generationDate}
  and last_status = 'RUNNING'
  and api_call_count = #{attemptNo}

mapper.select:
select count(*)
from one_line_strategy_ai_draft
where generation_date = #{generationDate}

mapper.update:
update one_line_strategy_ai_draft
set status = 'APPROVING',
    reviewed_at = now(),
    reviewed_by = #{reviewedBy}
where draft_id = #{draftId}
  and status = 'PENDING'

update one_line_strategy_ai_draft
set status = 'REJECTED',
    reviewed_at = now(),
    reviewed_by = #{reviewedBy}
where draft_id = #{draftId}
  and status = 'PENDING'
